{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q9",
      "policy_quote": "Before taking any actions that update the booking database (booking, modifying flights, editing baggage, changing cabin class, or updating passenger information), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must explicitly confirm with the user (via a message) the details of the flight modification (date, cabin, route, and payment method for refund) before proceeding."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q9",
      "policy_quote": "You should not provide any information, knowledge, or procedures not provided by the user or available tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must avoid providing unsolicited information, recommendations, or comments beyond what is explicitly requested or confirmed by the user."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q12",
      "policy_quote": "First, the agent must obtain the user id and reservation id.",
      "requirement": "The assistant must ensure the user ID and reservation ID are provided or confirmed before updating the reservation."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q12",
      "policy_quote": "Change cabin: Cabin cannot be changed if any flight in the reservation has already been flown.",
      "requirement": "The assistant must verify that no flight in the reservation has already departed before changing the cabin class."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q12",
      "policy_quote": "Cabin class must remain the same across all the flights in the same reservation; changing cabin for just one flight segment is not possible.",
      "requirement": "The assistant must ensure the cabin class is uniformly applied to all flights in the reservation."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q12",
      "policy_quote": "If the price after cabin change is lower than the original price, the user is should be refunded the difference.",
      "requirement": "The assistant must process a refund for the price difference if the new cabin class is cheaper than the original."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q11",
      "policy_quote": "All payment methods must already be in the user profile for safety reasons.",
      "requirement": "The assistant must use a payment method already listed in the user's profile for refund processing."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q11",
      "policy_quote": "Each reservation can use at most one travel certificate, at most one credit card, and at most three gift cards.",
      "requirement": "The assistant must ensure the selected payment method for the refund adheres to the user's available and valid payment methods (e.g., no exceeding limits on gift cards)."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q9",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously.",
      "requirement": "The assistant must not respond to the user while making a tool call to update the reservation."
    }
  ]
}
